import { readdir, writeFile } from 'node:fs/promises'
import path from 'node:path'
import sharp from 'sharp'

const directory = 'public/portfolio/cases'
const sizes = {}
for (const name of (await readdir(directory)).sort()) {
  if (!/\.(webp|png|jpe?g)$/.test(name)) continue
  const { width, height } = await sharp(path.join(directory, name)).metadata()
  sizes[`/portfolio/cases/${name}`] = { width, height }
}
await writeFile(
  'src/data/portfolio-case-image-sizes.ts',
  '// Generated by node scripts/prepare-case-image-sizes.mjs. Preserve intrinsic ratios.\n' +
    'export const caseImageSizes: Record<string, { width: number; height: number }> = ' +
    JSON.stringify(sizes, null, 2) +
    '\n'
)
